{"styles":{"color":{"background":"#171a21","text":"#f1f1f1"},"elements":{"link":{"color":{"text":"#f1f1f1"}},"button":{"color":{"text":"#f35b1c"}}},"css":"/* ===== MÀU CHUNG ===== */
body:not(.wp-admin):not(.login) {
 --space-bg: #10091d;
 --space-panel: #21132f;
 --space-text: #f3efff;
 --space-muted: #cec1df;
 --space-green: #86efac;

 --wp--preset--color--base: #10091d;
 --wp--preset--color--base-2: #21132f;
 --wp--preset--color--contrast: #f3efff;
 --wp--preset--color--contrast-2: #cec1df;
 --wp--preset--color--contrast-3: #ab93c4;

 position: relative;
 isolation: isolate;
 color: var(--space-text);
 background: var(--space-bg);
}

/* ===== TINH VÂN TÍM ===== */
body:not(.wp-admin):not(.login)::before {
 content: "";
 position: fixed;
 inset: 0;
 z-index: 0;
 pointer-events: none;

 background:
 radial-gradient(
 ellipse at 12% 25%,
 rgba(109, 40, 217, 0.45),
 transparent 52%
 ),
 radial-gradient(
 ellipse at 85% 60%,
 rgba(147, 51, 234, 0.32),
 transparent 48%
 ),
 radial-gradient(
 ellipse at 50% 95%,
 rgba(59, 49, 164, 0.38),
 transparent 55%
 );

 background-size: 140% 140%;
 animation: space-nebula 35s ease-in-out infinite alternate;
}

/* ===== CÁC LỚP SAO ===== */
body:not(.wp-admin):not(.login)::after {
 content: "";
 position: fixed;
 inset: 0;
 z-index: 0;
 pointer-events: none;

 background-image:
 radial-gradient(
 1px 1px at 23px 31px,
 rgba(255, 255, 255, 0.9) 90%,
 transparent 100%
 ),
 radial-gradient(
 1px 1px at 79px 117px,
 rgba(219, 195, 255, 0.75) 90%,
 transparent 100%
 ),
 radial-gradient(
 1.5px 1.5px at 141px 65px,
 rgba(255, 255, 255, 0.8) 90%,
 transparent 100%
 ),
 radial-gradient(
 2px 2px at 53px 187px,
 rgba(190, 169, 255, 0.7) 65%,
 transparent 100%
 );

 background-size:
 173px 229px,
 283px 191px,
 367px 313px,
 467px 389px;

 background-repeat: repeat;
 opacity: 0.65;
 animation: space-stars 40s ease-in-out infinite alternate;
}

/* Nội dung nằm trên nền, không đổi vị trí thanh quản trị */
body:not(.wp-admin):not(.login) .wp-site-blocks {
 position: relative;
 z-index: 1;
 color: var(--space-text);
 background-color: transparent;
}

/* ===== CHỮ ===== */
body:not(.wp-admin):not(.login)
.wp-site-blocks :where(h1, h2, h3, h4, h5, h6, p, li, label) {
 color: var(--space-text);
}

body:not(.wp-admin):not(.login)
.wp-site-blocks figcaption {
 color: var(--space-muted);
}

/* ===== LIÊN KẾT ===== */
body:not(.wp-admin):not(.login)
.wp-site-blocks a:not(.wp-element-button):not(.wp-block-button__link) {
 color: var(--space-green);
 text-underline-offset: 0.18em;
}

body:not(.wp-admin):not(.login)
.wp-site-blocks a:not(.wp-element-button):not(.wp-block-button__link):hover {
 color: #bbf7d0;
}

/* ===== NÚT XANH LÁ ===== */
body:not(.wp-admin):not(.login)
.wp-site-blocks :is(.wp-element-button, .wp-block-button__link) {
 color: #102018;
 background: var(--space-green);
 border: 1px solid var(--space-green);
 border-radius: 10px;
 text-decoration: none;
 box-shadow: 0 0 18px rgba(134, 239, 172, 0.15);
 transition:
 transform 180ms ease,
 box-shadow 180ms ease,
 background-color 180ms ease;
}

body:not(.wp-admin):not(.login)
.wp-site-blocks :is(.wp-element-button, .wp-block-button__link):hover {
 color: #102018;
 background: #4ade80;
 border-color: #4ade80;
 box-shadow: 0 0 26px rgba(134, 239, 172, 0.3);
 transform: translateY(-2px);
}

/* ===== BẢNG THÔNG SỐ ===== */
body:not(.wp-admin):not(.login)
.wp-site-blocks .wp-block-table table {
 color: var(--space-text);
 background: var(--space-panel);
 border-collapse: collapse;
}

body:not(.wp-admin):not(.login)
.wp-site-blocks .wp-block-table :is(th, td) {
 color: var(--space-text);
 border: 1px solid #66517c;
 padding: 12px 16px;
}

body:not(.wp-admin):not(.login)
.wp-site-blocks .wp-block-table thead {
 background: #38204f;
 border-color: #66517c;
}

body:not(.wp-admin):not(.login)
.wp-site-blocks .wp-block-table tbody tr {
 background: var(--space-panel);
}

body:not(.wp-admin):not(.login)
.wp-site-blocks .wp-block-table tbody tr:nth-child(even) {
 background: #2b1b3b;
}

/* ===== MENU ĐIỆN THOẠI ===== */
body:not(.wp-admin):not(.login)
.wp-site-blocks .wp-block-navigation__responsive-container.is-menu-open {
 color: var(--space-text);
 background: var(--space-bg);
}

body:not(.wp-admin):not(.login)
.wp-site-blocks :is(
 .wp-block-navigation__responsive-container-open,
 .wp-block-navigation__responsive-container-close
) {
 color: var(--space-text);
}

/* ===== FOCUS KHI DÙNG BÀN PHÍM ===== */
body:not(.wp-admin):not(.login)
.wp-site-blocks :is(a, button, input, select, textarea):focus-visible {
 outline: 3px solid var(--space-green);
 outline-offset: 4px;
}

/* ===== CHUYỂN ĐỘNG ===== */
@keyframes space-nebula {
 from {
 background-position: 0% 0%;
 }
 to {
 background-position: 100% 70%;
 }
}

@keyframes space-stars {
 from {
 background-position:
 0 0, 0 0, 0 0, 0 0;
 opacity: 0.55;
 }
 to {
 background-position:
 8px -20px,
 -12px -12px,
 6px -28px,
 -8px -16px;
 opacity: 0.8;
 }
}

/* Tôn trọng thiết lập giảm chuyển động */
@media (prefers-reduced-motion: reduce) {
 body:not(.wp-admin):not(.login)::before,
 body:not(.wp-admin):not(.login)::after {
 animation: none;
 }

 body:not(.wp-admin):not(.login)
 .wp-site-blocks :is(.wp-element-button, .wp-block-button__link) {
 transition: none;
 }

 body:not(.wp-admin):not(.login)
 .wp-site-blocks :is(.wp-element-button, .wp-block-button__link):hover {
 transform: none;
 }
}"},"settings":{"color":{"palette":{"theme":[{"color":"#f9f9f9","name":"Base","slug":"base"},{"color":"#ffffff","name":"Base / Two","slug":"base-2"},{"color":"#111111","name":"Contrast","slug":"contrast"},{"color":"#636363","name":"Contrast / Two","slug":"contrast-2"},{"color":"#A4A4A4","name":"Contrast / Three","slug":"contrast-3"},{"color":"#cfcabe","name":"Accent","slug":"accent"},{"color":"#c2a990","name":"Accent / Two","slug":"accent-2"},{"color":"#f5f5f0","name":"Accent / Three","slug":"accent-3"},{"color":"#b1c5a4","name":"Accent / Four","slug":"accent-4"},{"color":"#b5bdbc","name":"Accent / Five","slug":"accent-5"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}
